tryItExercises.solutionCode:
const express = require("express");

const app = express();
app.use(express.json());

function validateWorkshop(input) {
  const fields = [];
  if (!input.title || typeof input.title !== "string") fields.push("title");
  if (typeof input.seats !== "number" || input.seats <= 0) fields.push("seats");
  return fields;
}

app.post("/api/workshops", (req, res) => {
  const fields = validateWorkshop(req.body);

  if (fields.length > 0) {
    return res.status(400).json({
      error: "Validation failed",
      fields,
    });
  }

  return res.status(200).json({ accepted: true });
});

app.listen(3000, "127.0.0.1", () => {
  console.log("API listening on http://127.0.0.1:3000");
});
